@startuml

class SensorController {
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class LastValue {
  + value : float
}

abstract class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

class EMonitor {}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Apartment "1" -- "*" Inhabitant
SensorController "1" -- "*" Sensor
SensorController "1" -- "1" EMonitor
Room "1" *-- "1" Sensor
Sensor "1" *-- "*" MeasuredValue
Sensor "1" --> "0..1" LastValue

@enduml

